/**
 * Original design and implementation by Gustavo Fior (@gustavo-fior),
 * with co-founder Abdul Haidar at Foglamp Labs. Apache-2.0.
 * Extracted AS-IS from foglamp-labs/foglamp: apps/web/src/components/scan/kinds.tsx.
 */

import type { NodeKind } from "../../lib/scan/scan";
import {
	IconBoltFilled,
	IconClockFilled,
	IconDatabaseFilled,
	IconGhostFilled,
	IconHexagonFilled,
	type IconProps,
	IconSparklesFilled,
	IconTool,
	IconWorldFilled,
} from "@tabler/icons-react";
import type { ComponentType } from "react";

export interface KindStyle {
	label: string;
	Glyph: ComponentType<IconProps>;
	/** Extra classes for the glyph (e.g. fill outline icons). */
	glyphClass?: string;
	/** Legend dot / accent background. */
	bar: string;
	/** Node icon chip (tint background + foreground). */
	icon: string;
	/** Foreground tint for standalone glyphs (legend, popover). */
	text: string;
	/** Raw color (Tailwind 500) for SVG strokes — edge pulses. */
	hex: string;
}

export const KIND_STYLES: Record<NodeKind, KindStyle> = {
	entry: {
		label: "Entry",
		Glyph: IconBoltFilled,
		bar: "bg-foreground/30",
		icon: "bg-muted text-foreground",
		text: "text-foreground/70",
		hex: "#64748b",
	},
	cron: {
		label: "Cron",
		Glyph: IconClockFilled,
		bar: "bg-amber-500",
		icon: "bg-amber-500/10 text-amber-600 dark:text-amber-400",
		text: "text-amber-600 dark:text-amber-400",
		hex: "#f59e0b",
	},
	agent: {
		label: "Agent",
		Glyph: IconGhostFilled,
		bar: "bg-orange-500",
		icon: "bg-orange-500/10 text-orange-600 dark:text-orange-400",
		text: "text-orange-600 dark:text-orange-400",
		hex: "#f97316",
	},
	model: {
		label: "Model",
		Glyph: IconSparklesFilled,
		bar: "bg-blue-500",
		icon: "bg-blue-500/10 text-blue-600 dark:text-blue-400",
		text: "text-blue-600 dark:text-blue-400",
		hex: "#3b82f6",
	},
	tool: {
		label: "Tool",
		Glyph: IconTool,
		glyphClass: "fill-current",
		bar: "bg-violet-500",
		icon: "bg-violet-500/10 text-violet-600 dark:text-violet-400",
		text: "text-violet-600 dark:text-violet-400",
		hex: "#8b5cf6",
	},
	service: {
		label: "Service",
		Glyph: IconHexagonFilled,
		bar: "bg-pink-500",
		icon: "bg-pink-500/10 text-pink-600 dark:text-pink-400",
		text: "text-pink-600 dark:text-pink-400",
		hex: "#ec4899",
	},
	store: {
		label: "Store",
		Glyph: IconDatabaseFilled,
		bar: "bg-emerald-500",
		icon: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
		text: "text-emerald-600 dark:text-emerald-400",
		hex: "#10b981",
	},
	external: {
		label: "External",
		Glyph: IconWorldFilled,
		bar: "bg-sky-500",
		icon: "bg-sky-500/10 text-sky-600 dark:text-sky-400",
		text: "text-sky-600 dark:text-sky-400",
		hex: "#0ea5e9",
	},
